import type { ProductRequest } from "../types.js";
import { compileDomain, type DomainSpec } from "../domain.js";

interface DomainExperience {
  formTitle: string;
  nameLabel: string;
  detailLabel: string;
  namePlaceholder: string;
  detailPlaceholder: string;
  primaryAction: string;
  activityTitle: string;
  emptyCopy: string;
  stages: string[];
}

function safeJson(value: unknown): string {
  return JSON.stringify(value);
}

function experienceFor(domain: DomainSpec): DomainExperience {
  switch (domain.kind) {
    case "booking":
      return {
        formTitle: "Nueva reserva",
        nameLabel: "Cliente",
        detailLabel: "Servicio, fecha y horario",
        namePlaceholder: "Ej.: María López",
        detailPlaceholder: "Ej.: Corte · viernes 18:00",
        primaryAction: "Crear reserva",
        activityTitle: "Agenda de reservas",
        emptyCopy: "Todavía no hay reservas. Creá la primera para validar la agenda.",
        stages: ["pendiente", "confirmada", "completada"]
      };
    case "marketplace":
      return {
        formTitle: "Publicar necesidad",
        nameLabel: "Cliente o empresa",
        detailLabel: "Necesidad y presupuesto",
        namePlaceholder: "Ej.: Hotel Costa Norte",
        detailPlaceholder: "Ej.: músico para evento · R$ 800",
        primaryAction: "Publicar oportunidad",
        activityTitle: "Oportunidades y propuestas",
        emptyCopy: "No hay oportunidades publicadas. Creá la primera para iniciar el matching.",
        stages: ["publicada", "con propuestas", "contratada"]
      };
    case "services":
      return {
        formTitle: "Solicitar servicio",
        nameLabel: "Cliente",
        detailLabel: "Trabajo y ubicación",
        namePlaceholder: "Ej.: Sergio",
        detailPlaceholder: "Ej.: reparar ducha · Canasvieiras",
        primaryAction: "Solicitar servicio",
        activityTitle: "Servicios en operación",
        emptyCopy: "No hay servicios activos. Creá la primera solicitud para probar el flujo operativo.",
        stages: ["solicitado", "cotizando", "asignado", "completado"]
      };
    case "commerce":
      return {
        formTitle: "Nuevo pedido",
        nameLabel: "Cliente",
        detailLabel: "Producto y cantidad",
        namePlaceholder: "Ej.: Cliente 001",
        detailPlaceholder: "Ej.: 2 × Producto A",
        primaryAction: "Crear pedido",
        activityTitle: "Pedidos",
        emptyCopy: "Todavía no hay pedidos. Creá el primero para validar el circuito comercial.",
        stages: ["nuevo", "preparando", "entregado"]
      };
    default:
      return {
        formTitle: "Nuevo registro",
        nameLabel: domain.entities[0] ?? "Nombre",
        detailLabel: "Detalle",
        namePlaceholder: "Nombre principal",
        detailPlaceholder: domain.actions[0] ?? "Detalle",
        primaryAction: domain.actions[0] ?? "Crear",
        activityTitle: "Actividad principal",
        emptyCopy: "Todavía no hay actividad. Creá el primer registro para probar el flujo.",
        stages: ["nuevo", "en curso", "completado"]
      };
  }
}

export function generateWebProject(request: ProductRequest, domain: DomainSpec = compileDomain(request.idea)): Record<string, string> {
  const title = request.idea.length > 72 ? `${request.idea.slice(0, 69)}...` : request.idea;
  const experience = experienceFor(domain);

  return {
    "generated/package.json": JSON.stringify({
      name: "generated-maestroarch-app",
      version: "0.1.0",
      private: true,
      scripts: { dev: "next dev", build: "next build", start: "next start" },
      dependencies: { next: "^15.2.0", react: "^19.0.0", "react-dom": "^19.0.0" },
      devDependencies: { "@types/node": "^22.10.0", "@types/react": "^19.0.0", typescript: "^5.7.2" }
    }, null, 2) + "\n",
    "generated/tsconfig.json": JSON.stringify({
      compilerOptions: {
        target: "ES2017",
        lib: ["dom", "dom.iterable", "esnext"],
        allowJs: false,
        skipLibCheck: true,
        strict: true,
        noEmit: true,
        esModuleInterop: true,
        module: "esnext",
        moduleResolution: "bundler",
        resolveJsonModule: true,
        isolatedModules: true,
        jsx: "preserve",
        incremental: true,
        plugins: [{ name: "next" }]
      },
      include: ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts"],
      exclude: ["node_modules"]
    }, null, 2) + "\n",
    "generated/next-env.d.ts": "/// <reference types=\"next\" />\n/// <reference types=\"next/image-types/global\" />\n",
    "generated/app/layout.tsx": `import type { ReactNode } from "react";\nimport "./globals.css";\n\nexport const metadata = { title: ${safeJson(title)}, description: "Generated by MaestroArch" };\n\nexport default function RootLayout({ children }: { children: ReactNode }) {\n  return <html lang=\"es\"><body>{children}</body></html>;\n}\n`,
    "generated/app/page.tsx": `"use client";\n\nimport { FormEvent, useEffect, useState } from "react";\n\ntype RecordItem = { id: string; name: string; detail: string; status: string };\n\nconst idea = ${safeJson(request.idea)};\nconst domain = ${safeJson(domain.title)};\nconst kind = ${safeJson(domain.kind)};\nconst entities = ${safeJson(domain.entities)} as string[];\nconst actions = ${safeJson(domain.actions)} as string[];\nconst sections = ${safeJson(domain.sections)} as string[];\nconst experience = ${safeJson(experience)} as { formTitle:string; nameLabel:string; detailLabel:string; namePlaceholder:string; detailPlaceholder:string; primaryAction:string; activityTitle:string; emptyCopy:string; stages:string[] };\nconst storageKey = \"maestroarch:\" + kind + \":records\";\n\nexport default function Home() {\n  const [records, setRecords] = useState<RecordItem[]>([]);\n  const [name, setName] = useState(\"\");\n  const [detail, setDetail] = useState(\"\");\n\n  useEffect(() => {\n    try {\n      const saved = localStorage.getItem(storageKey);\n      if (saved) setRecords(JSON.parse(saved));\n    } catch {}\n  }, []);\n\n  useEffect(() => {\n    localStorage.setItem(storageKey, JSON.stringify(records));\n  }, [records]);\n\n  function addRecord(event: FormEvent) {\n    event.preventDefault();\n    if (!name.trim()) return;\n    setRecords((current) => [{ id: crypto.randomUUID(), name: name.trim(), detail: detail.trim(), status: experience.stages[0] ?? \"nuevo\" }, ...current]);\n    setName(\"\");\n    setDetail(\"\");\n  }\n\n  function advance(id: string) {\n    setRecords((current) => current.map((item) => {\n      if (item.id !== id) return item;\n      const index = Math.max(0, experience.stages.indexOf(item.status));\n      const next = experience.stages[Math.min(index + 1, experience.stages.length - 1)] ?? item.status;\n      return { ...item, status: next };\n    }));\n  }\n\n  function remove(id: string) {\n    setRecords((current) => current.filter((item) => item.id !== id));\n  }\n\n  return (\n    <main className=\"shell\">\n      <section className=\"hero\">\n        <p className=\"eyebrow\">MaestroArch · MVP generado</p>\n        <h1>{domain}</h1>\n        <p className=\"idea\">{idea}</p>\n        <nav className=\"pills\" aria-label=\"Secciones del producto\">{sections.map((item) => <span className=\"pill\" key={item}>{item}</span>)}</nav>\n      </section>\n\n      <section className=\"grid\">\n        <article className=\"card\">\n          <p className=\"eyebrow\">Acción primaria</p>\n          <h2>{experience.formTitle}</h2>\n          <form onSubmit={addRecord} className=\"form\">\n            <label>{experience.nameLabel}<input value={name} onChange={(e) => setName(e.target.value)} placeholder={experience.namePlaceholder} /></label>\n            <label>{experience.detailLabel}<input value={detail} onChange={(e) => setDetail(e.target.value)} placeholder={experience.detailPlaceholder} /></label>\n            <button type=\"submit\">{experience.primaryAction}</button>\n          </form>\n        </article>\n\n        <article className=\"card\">\n          <p className=\"eyebrow\">Modelo del dominio</p>\n          <h2>Qué administra</h2>\n          <ul>{entities.map((item) => <li key={item}>{item}</li>)}</ul>\n          <div className=\"miniFlow\">{actions.slice(0, 4).map((item, index) => <span key={item}><b>{index + 1}</b>{item}</span>)}</div>\n        </article>\n      </section>\n\n      <section className=\"card flow\">\n        <div className=\"flowHeader\"><div><p className=\"eyebrow\">Flujo principal</p><h2>{experience.activityTitle}</h2></div><strong>{records.length} registros</strong></div>\n        {records.length === 0 ? <p className=\"empty\">{experience.emptyCopy}</p> : (\n          <div className=\"records\">{records.map((item) => {\n            const stageIndex = experience.stages.indexOf(item.status);\n            const done = stageIndex === experience.stages.length - 1;\n            const nextAction = actions[Math.min(Math.max(stageIndex + 1, 0), actions.length - 1)] ?? \"Avanzar\";\n            return (\n              <article className=\"record\" key={item.id}>\n                <div><strong>{item.name}</strong><p>{item.detail || \"Sin detalle\"}</p><span className=\"status\">{item.status}</span></div>\n                <div className=\"recordActions\">{!done && <button onClick={() => advance(item.id)}>{nextAction}</button>}<button className=\"ghost\" onClick={() => remove(item.id)}>Eliminar</button></div>\n              </article>\n            );\n          })}</div>\n        )}\n      </section>\n    </main>\n  );\n}\n`,
    "generated/app/globals.css": `*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;background:#08111f;color:#f7f8fb}.shell{min-height:100vh;padding:40px 20px;max-width:1100px;margin:auto}.hero{padding:28px 0}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.14em;opacity:.7;margin:0}.hero h1{font-size:clamp(34px,7vw,68px);line-height:1;margin:14px 0}.idea{max-width:800px;color:#c7d2e5;font-size:18px}.pills{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}.pill,.status{padding:8px 11px;border:1px solid #32445f;border-radius:999px;background:#101b2e;font-size:13px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px}.card{background:#101b2e;border:1px solid #263752;border-radius:20px;padding:24px;box-shadow:0 18px 60px rgba(0,0,0,.22)}.card h2{margin-top:8px}.card li{margin:10px 0}.form{display:grid;gap:14px}.form label{display:grid;gap:7px;font-size:13px;color:#c7d2e5}.form input{width:100%;padding:12px 14px;border-radius:12px;border:1px solid #32445f;background:#08111f;color:white}.form button,.recordActions button{border:0;border-radius:12px;padding:12px 16px;font-weight:700;cursor:pointer;background:white;color:#08111f}.miniFlow{display:grid;gap:8px;margin-top:20px}.miniFlow span{display:flex;gap:10px;align-items:center;color:#c7d2e5}.miniFlow b{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:#233552;color:white}.flow{margin-top:18px}.flowHeader{display:flex;align-items:center;justify-content:space-between;gap:20px}.empty{padding:24px 0;color:#9fb0c9}.records{display:grid;gap:12px}.record{display:flex;justify-content:space-between;gap:20px;padding:16px;border-radius:14px;background:#0b1526;border:1px solid #263752}.record p{margin:6px 0 12px;color:#b9c5d8}.recordActions{display:flex;gap:8px;align-items:center}.recordActions .ghost{background:transparent;color:#dbe4f2;border:1px solid #32445f}@media(max-width:640px){.record{flex-direction:column}.recordActions{align-items:stretch}.recordActions button{flex:1}.flowHeader{align-items:flex-start;flex-direction:column}}\n`,
    "generated/DOMAIN.json": JSON.stringify(domain, null, 2) + "\n",
    "generated/DOMAIN_FLOW.json": JSON.stringify(experience, null, 2) + "\n",
    "generated/README.md": `# App generada por MaestroArch\n\n## Idea\n${request.idea}\n\n## Dominio detectado\n${domain.title} (${domain.kind})\n\n## Qué funciona\n- flujo y formulario específicos para el dominio;\n- creación de registros;\n- ciclo de estados propio del dominio;\n- eliminación;\n- persistencia local en el navegador;\n- interfaz responsive;\n- build de Next.js.\n\n## Ejecutar\n\n\`\`\`bash\nnpm install\nnpm run dev\n\`\`\`\n\n## Build\n\n\`\`\`bash\nnpm run build\n\`\`\`\n`
  };
}
